#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header line lost"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other booking (kaede) lost"; fail=1; }
# not found: exit 1, message on stderr only, nothing on stdout
o=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); s=$?
[ $s = 1 ] || { echo "not found should exit 1, got $s"; fail=1; }
[ -z "$o" ] || { echo "not found should print nothing to stdout: $o"; fail=1; }
e=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null)
[ "$e" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found stderr: $e"; fail=1; }
# usage error: exit 2, message on stderr only
o=$(bash src/cancel.sh aoi 2>/dev/null); s=$?
[ $s = 2 ] || { echo "usage should exit 2, got $s"; fail=1; }
[ -z "$o" ] || { echo "usage should print nothing to stdout: $o"; fail=1; }
e=$(bash src/cancel.sh aoi 2>&1 >/dev/null)
